"""Build the project report from verified results; no manually typed result values."""
from pathlib import Path
import json
import pandas as pd
import numpy as np
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Image,Table,TableStyle,PageBreak,KeepTogether
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.pagesizes import A4
ROOT=Path(__file__).resolve().parents[1]
for name,f in [('Arial','Arial.ttf'),('Arial-Bold','Arial Bold.ttf'),('Arial-Italic','Arial Italic.ttf')]:pdfmetrics.registerFont(TTFont(name,'/System/Library/Fonts/Supplemental/'+f))
pdfmetrics.registerFontFamily('Arial',normal='Arial',bold='Arial-Bold',italic='Arial-Italic',boldItalic='Arial-Bold')
B=ParagraphStyle('body',fontName='Arial',fontSize=12,leading=14.4,spaceAfter=10,textColor=colors.HexColor('#243644'))
H=ParagraphStyle('h',parent=B,fontName='Arial-Bold',fontSize=19,leading=23,spaceAfter=17,textColor=colors.HexColor('#15354B'))
S=ParagraphStyle('sub',parent=B,fontName='Arial-Bold',fontSize=13,leading=16,spaceBefore=4,spaceAfter=8)
C=ParagraphStyle('caption',parent=B,fontSize=12,leading=14.4,textColor=colors.HexColor('#526675'))
TB=ParagraphStyle('table',parent=B,fontSize=12,leading=14,spaceAfter=0)
T=ParagraphStyle('title',parent=H,fontSize=27,leading=32,spaceAfter=16)
story=[]
def p(t):story.append(Paragraph(t,B))
def h(t):story.append(Paragraph(t,H))
def sub(t):story.append(Paragraph(t,S))
def page(title):
    if story:story.append(PageBreak())
    h(title)
def fig(name,caption,width=490):
    from PIL import Image as PILImage
    path=ROOT/'figures'/f'{name}.png';w,hh=PILImage.open(path).size
    story.append(Image(str(path),width=width,height=width*hh/w));story.append(Spacer(1,7));story.append(Paragraph(caption,C))
def table(headers,rows,widths):
    vals=[[Paragraph(str(x),TB) for x in headers]]+[[Paragraph(str(x),TB) for x in r] for r in rows]
    t=Table(vals,colWidths=widths,hAlign='LEFT',repeatRows=1)
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#E8EEF2')),('LINEBELOW',(0,0),(-1,0),.8,colors.HexColor('#254862')),('LINEBELOW',(0,-1),(-1,-1),.7,colors.HexColor('#254862')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]))
    story.append(t);story.append(Spacer(1,12))
def footer(c,doc):
    c.setFont('Arial',9);c.setFillColor(colors.HexColor('#6B7C89'));c.drawString(48,29,'LSGI3213  |  MATSim equil scenario experiment');c.drawRightString(A4[0]-48,29,str(doc.page))

def main():
    raw=pd.read_csv(ROOT/'analysis/summary_by_run.csv');d=raw[raw.scenario!='original100'];g=d.groupby('scenario').mean(numeric_only=True)
    order=['baseline','capacity','stagger','combined','adaptive'];labels={'baseline':'Baseline','capacity':'Capacity','stagger':'Stagger','combined':'Combined','adaptive':'Adaptive'}
    def v(s,k):return float(g.loc[s,k])
    def f(s,k,n=2):return f'{v(s,k):.{n}f}'
    def improve(s):return 100*(1-v(s,'am_mean_min')/v('baseline','am_mean_min'))
    def read(s,k,seed=4711):return pd.read_csv(ROOT/'analysis'/f'{s}_s{seed}_{k}.csv.gz')
    original=raw[raw.scenario=='original100'].iloc[0]
    sensitivity=json.loads((ROOT/'analysis/sensitivity.json').read_text()) if (ROOT/'analysis/sensitivity.json').exists() else None
    assert len(d)==15,'All 15 main runs must be complete'
    story.append(Paragraph('Capacity, departure scheduling<br/>and congestion in MATSim',T))
    p('<b>Developing and evaluating scenarios with the official equil network</b><br/>LSGI3213: Intelligent Transportation Systems<br/>Computational project report | 8 September 2026')
    sub('Abstract')
    p(f'This project examines how road capacity and departure scheduling influence travel in a synthetic agent-based network. Public, version-tagged MATSim 12.0 equil inputs were downloaded and verified against the tutorial distribution. The original 100-agent example was reproduced, and the supplied 2,000-agent population was used to define a separate congestion benchmark. Five main scenarios compare unchanged supply, doubled capacity on nine corridor links, departures spread symmetrically across one hour, their combination, and a configuration allowing departure-time learning. Each was executed for iterations 0-100 with three random seeds.')
    p(f'All 4,000 planned car trips completed in every main run, with zero stuck events. Across seeds, mean morning travel time was {f("baseline","am_mean_min")} minutes in the benchmark, {f("capacity","am_mean_min")} after expansion, {f("stagger","am_mean_min")} with staggering, {f("combined","am_mean_min")} with both, and {f("adaptive","am_mean_min")} with adaptive timing. These changes correspond to reductions of {improve("capacity"):.1f}%, {improve("stagger"):.1f}%, {improve("combined"):.1f}% and {improve("adaptive"):.1f}%, respectively. Trip distributions, executed-plan scores and event-derived link conditions reveal both average benefits and differences among agents.')
    p('The exercise demonstrates a reproducible ITS scenario workflow, rather than a forecast for a real city. Its main limitations are synthetic demand, fixed activity locations, car-only travel, simplified queue dynamics and a small number of stochastic replications. Plan scores are model-specific utility measures; they are not monetary welfare. A complete replication package contains downloaded inputs, scenario XML, run logs, event files, derived results and figure/report source code.')
    p('<b>Keywords:</b> MATSim; equil; traffic simulation; departure scheduling; capacity; intelligent transportation systems')

    page('1  Background and research questions')
    p('A transport network can experience congestion even when the total number of travellers remains unchanged. The concentration of departures and the allocation of those travellers across routes determine how quickly demand reaches individual road links. Capacity improvements act on supply, while departure scheduling acts on when demand arrives. An ITS analysis should therefore inspect both traffic performance and the behaviour generating that traffic, rather than reporting only a single network-wide average.')
    p('MATSim provides a useful controlled environment for this question because individual agents execute activity plans and experience congestion created by other agents. The equil network offers several parallel outward corridors with a shared return path. Its small size makes the link-level mechanism inspectable. Choosing this example also preserves the assignment requirement to start from equil or chessboard; an unrelated metropolitan road download would not directly satisfy that requirement [1,2].')
    sub('Questions addressed')
    p('<b>RQ1:</b> How much does doubling the discharge capacity of the nine outward corridor links reduce morning travel time and alter their use?<br/><br/><b>RQ2:</b> Can a one-hour spread of planned departures reduce congestion without changing the number of travellers or their activity locations?<br/><br/><b>RQ3:</b> Does combining both interventions provide an additional benefit, or do they address the same queues?<br/><br/><b>RQ4:</b> What changes when departure times are learned through the MATSim configuration rather than assigned externally?')
    p('The hypotheses are directional, not predetermined results: expansion is expected to shorten queues, staggering is expected to reduce their formation, and their joint gain may be smaller than the sum of separate gains. Timing adaptation may improve daily scores, but its score benefit need not equal its travel-time benefit because activity timing also enters the scoring system. The completed simulations, rather than these expectations, determine the findings.')
    p('This is a within-model intervention comparison. Common inputs and paired seeds improve comparability, but do not establish external validity. Neither the network coordinates nor the population represent observed Hong Kong residents. No observed counts, household survey or traffic-speed dataset is available for calibration. The analysis consequently makes conditional statements about the constructed experiment.')

    page('2  MATSim framework and mechanisms')
    p('MATSim executes individual daily activity plans on a transport network. A plan describes activities, locations, timing and the trips joining those activities. Network supply is represented by directed links with lengths, free speeds, lanes and capacities. The mobility simulation produces events such as departures, arrivals and link entries or exits. These events support both behavioural scoring and the performance indicators used in this report [3,4].')
    sub('The repeated simulation cycle')
    p('In each iteration, agents select plans, execute them together, receive scores and may revise their plans for a subsequent iteration. In the main fixed-time scenarios, BestScore has weight 0.9 and ReRoute has weight 0.1. Agents retain at most five plans. BestScore chooses among remembered alternatives; ReRoute provides route innovation. Repeated interaction can improve experienced scores, although a finite simulation and a stable average do not prove convergence to an exact equilibrium [2,5].')
    p('QSim represents traffic using a queue-based network loading mechanism. A vehicle must spend at least the free-speed traversal time on a full link, then compete for discharge subject to flow and downstream constraints. This is not a detailed car-following simulation. Increasing the capacity attribute changes discharge flow but, in this experiment, does not add a physical lane or increase storage. Those distinctions limit the engineering interpretation of the expansion scenario [3,4].')
    sub('Scoring and time choices')
    p('The supplied configuration uses a performing utility of +6 utils per hour, car-travel utility of -6 utils per hour and a late-arrival coefficient of -18 utils per hour. Typical home and work durations are 12 and 8 hours. Work opens at 07:00, closes at 18:00 and has a latest start time of 09:00. The full activity utility is nonlinear and includes timing conditions: these coefficients do not imply that the final plan score is simply a linear function of travel minutes [2,5].')
    p('The adaptive scenario replaces 0.1 of the BestScore weight with TimeAllocationMutator. Its mutation range is 1,800 seconds and mutationAffectsDuration is false, so the explicit work duration is retained while eligible activity end times can change. Repeated mutations can accumulate across iterations. Therefore, the mutation range is a per-change limit, not a permanent one-hour departure window [6].')

    page('3  Public data and provenance')
    p('The assignment mentions input ZIP files hosted on Blackboard. Those specific ZIP files were not accessed. Instead, five inputs were retrieved from the official matsim-org/matsim-libs repository at the matsim-12.0 tag. All five downloaded files were byte-identical to the corresponding files already present inside the local Mac tutorial distribution. This is direct evidence of agreement with the tutorial examples, but it cannot prove identity with an unseen Blackboard project ZIP [1,2].')
    table(['Public file','Role and audit result'],[['network.xml','15 nodes; 23 directed links; synthetic coordinates'],['facilities.xml','23 facilities with home/work activity options'],['config.xml','Original 100-agent example and scoring settings'],['plans100.xml','100 people; 201 planned trips; source reference'],['plans2000.xml.gz','2,000 people; home-work-home; 4,000 trips']], [145,350])
    p('The repository inputs are synthetic demonstration data. They are suitable for the chosen controlled scenario but must not be labelled as measured traffic. The optional counts file was not used as a calibration dataset. Each downloaded file has a saved URL, retrieval timestamp, GitHub blob identifier, SHA-256 digest and byte count in data/source_manifest.json. The local comparison is recorded independently in data/local_comparison.json.')
    p('The 2,000-agent file contains legacy v4 route descriptions. For the five congestion scenarios, those embedded routes and departure-time hints on legs are removed consistently, allowing MATSim to generate routes on the retained network. Activity links, facilities, modes and work duration remain unchanged. This preprocessing is applied to the benchmark as well as every intervention; it is not a treatment-specific advantage. Raw downloads are retained separately and never rewritten.')
    p('The source 100-person file is retained without this preprocessing. It includes one extra same-location work-to-work trip, and its work schedules differ from the 2,000-agent file. Its result is therefore reported as a reproduction check, not used to estimate the effect of multiplying population size. The five main scenarios all use the same 2,000 people and differ only in the declared interventions.')

    page('4  Base network and daily activities')
    fig('01_network','Figure 1. Official equil topology. Node and link labels are identifiers; red links 11-19 are the capacity treatment. The coordinates show a synthetic layout, not a geographic map. Link lengths are taken from XML and need not equal straight-line distances.',475)
    p('All 2,000 agents start at activity link 1, travel to work at link 20, perform an eight-hour work activity and return home. In the congestion benchmark, first departures are all scheduled at 06:00. Nine outward alternatives connect node 2 to node 12 through nodes 3-11. Their upstream links 2-10 have capacities of 3,600 vehicles per hour, while links 11-19 each provide 1,000 vehicles per hour. The latter are the deliberately targeted corridor bottlenecks.')
    p('The nine treatment links each have a declared length of 5 km, one lane and free speed of 27.78 metres per second. Their combined nominal flow capacity is 9,000 vehicles per hour. Other connector and return links have much higher flow capacities. The return path is longer than the outward path, so morning and return journeys must be separated when interpreting daily averages. Endpoint treatment also means that dividing the sum of every XML link length by speed does not automatically reproduce trip duration.')
    p('Facilities are supplied and referenced by the 2,000-person plans. Their locations are held fixed to isolate route and timing responses. Neither residential relocation nor destination choice is enabled; differences in outcomes cannot be interpreted as evidence about longer-term land-use adjustment.')

    page('5  Scenario design and justification')
    table(['Scenario','Network / daily-plan change','Configuration'],[['Baseline','2,000 source agents; all depart 06:00','BestScore 0.9; ReRoute 0.1'],['Capacity','Links 11-19: 1,000 to 2,000 veh/h','Same as baseline'],['Stagger','First departure spread 05:30-06:30','Same as baseline'],['Combined','Both capacity and staggering','Same as baseline'],['Adaptive','Same initial inputs as baseline','BestScore 0.8; ReRoute 0.1; time mutation 0.1']], [85,240,170])
    p('The capacity scenario changes only discharge capacity on links 11-19. Link lengths, free speeds, lanes and all other link capacities are fixed. It tests operational flow capacity, not a fully costed road-widening proposal. The stagger scenario assigns deterministic midpoint quantiles across a 3,600-second interval: for zero-based person position i, departure equals 19,800 + (i + 0.5) x 3,600 / 2,000 seconds. The mean stays exactly 06:00 in the XML; one-second QSim discretisation may slightly alter realised times.')
    p('The staggered schedule is assigned by source-file order and kept identical across seeds. It is a controlled, perfect-compliance scheduling experiment. It does not estimate whether workers would accept earlier departures. The work activity still lasts eight hours from arrival, so return departure times can change even though work duration does not. The combination scenario permits a factorial comparison of overlapping benefits.')
    p('The adaptive scenario supplies a distinct configuration intervention. It retains baseline network supply and initial schedules, but permits endogenous timing changes under the unchanged scoring rules. Its outcome is compared with externally staggered schedules to illustrate the difference between assigned coordination and individual score-seeking behaviour. Because early work arrivals interact with the 07:00 opening time, a timing policy can affect scores beyond its effect on queues.')
    p('All main scenarios share the same scoring function, facility data, car mode, demand size, memory limit and iteration horizon. Increasing the horizon from the original 10 to 100 iterations is a common experimental control, rather than an intervention whose travel benefit is attributed to a policy.')

    page('6  Execution and measurement')
    p('The project uses the MATSim 12.0 executable supplied in the tutorial and Amazon Corretto Java 11.0.30 on this Mac. The JAR manifest identifies a Java 11 build. The tutorial suggests Java 14, but actual successful execution with Java 11 is documented in the saved logs. All simulations are run headlessly with a 2 GB maximum heap and one thread for QSim, global processing and event handling. No global Java settings or shell profile were changed.')
    table(['Control','Value / interpretation'],[['Main replications','5 scenarios x 3 seeds = 15 runs'],['Seeds','4711, 42, 2025; paired across scenarios'],['Iteration horizon','0-100 inclusive: 101 simulated days per run'],['Reference run','Original 100-person input; iterations 0-10'],['Evidence','Exit codes, console logs, output configuration, plans, events and native trip tables']], [140,355])
    p('Final-iteration event files are the primary measurement source. A trip begins with a car departure event and ends with its matching arrival. Trip duration is arrival minus departure. Stuck trips, unmatched departures and unmatched arrivals are checked explicitly. The independent event-derived durations are matched by person and trip number to every row of MATSim output_trips.csv.gz. Selected-plan mean scores are independently checked against the final avg. EXECUTED value in scorestats.txt.')
    p('Full-link traversal time is measured between entered-link and left-link events for the same vehicle and link. Delay is the nonnegative excess over XML length divided by free speed. Exit flow is exits per bin, scaled to an hourly rate. Occupancy integrates the vehicle count over time; density divides mean occupancy by link kilometres and lanes. Origin and destination activity links involve partial traversals. Traversal and flow measures for links 1 and 20 are marked missing; event-based occupancy and density are retained.')
    p('Results use both 5-minute and 15-minute bins for traffic concentration. A flow/capacity ratio is measured throughput relative to nominal flow capacity, not unmet demand. Empty traversal bins are missing observations rather than zero travel time. Cross-seed ranges describe simulation sensitivity, not confidence intervals for a real population.')

    page('7  Trip totals and travel performance')
    table(['Scenario','Trips / run','AM mean (min)','AM p95 (min)','Daily travel (h)'],[[labels[s],'4,000',f(s,'am_mean_min'),f(s,'am_p95_min'),f(s,'total_travel_h',1)] for s in order],[91,79,105,105,115])
    p('Table 4. Scenario results are arithmetic means of three final-iteration run summaries. AM p95 is the mean of the three within-run 95th percentiles, not a pooled percentile. Daily travel hours sum all completed trips in a run. Each run contains 2,000 first trips and 2,000 return trips, with zero stuck agents or unmatched trip events.')
    p(f'The capacity change lowers mean morning travel time by {v("baseline","am_mean_min")-v("capacity","am_mean_min"):.2f} minutes per agent ({improve("capacity"):.1f}%). Staggering lowers it by {v("baseline","am_mean_min")-v("stagger","am_mean_min"):.2f} minutes ({improve("stagger"):.1f}%). The combination lowers it by {v("baseline","am_mean_min")-v("combined","am_mean_min"):.2f} minutes ({improve("combined"):.1f}%). These comparisons hold demand size and activity locations fixed. They measure simulated time savings, not reductions in the number of journeys.')
    p(f'The adaptive configuration yields a morning average of {f("adaptive","am_mean_min")} minutes. Its daily mean across both directions is {f("adaptive","mean_trip_min")} minutes, compared with {f("baseline","mean_trip_min")} in the baseline. Reporting both quantities avoids obscuring the morning response with the longer, high-capacity return journey. The event analysis retains all completed trips rather than excluding slow trips to improve the result.')
    p(f'The separate original-data run completes {int(original.completed_trips)} trips for 100 agents and yields a morning mean of {original.am_mean_min:.2f} minutes and a mean executed score of {original.mean_score:.2f} utils. These values confirm a working example, but they are not the denominator of the treatment effects above. The source populations have different plan structures and schedules; their absolute scores should not be treated as a controlled population-size comparison.')

    page('8  Departure patterns and distributions')
    fig('04_departures','Figure 2. Realised first departures for seed 4711, shown with 15-minute and 5-minute bins. The baseline begins as a sharp pulse; external staggering and time learning redistribute departures. Capacity shares baseline initial timing, and Combined shares Stagger timing.',440)
    p(f'Baseline departure times are concentrated at 06:00. Staggering retains that mean but spreads the input schedule uniformly. Adaptive timing has a mean realised first departure of {f("adaptive","am_departure_mean_h",3)} hours and a within-run departure-time standard deviation averaging {f("adaptive","am_departure_sd_min")} minutes. This spread is an outcome of repeated replanning, not a directly imposed uniform schedule.')
    p('The 5-minute view preserves short pulses that a 15-minute histogram can hide. Counts are displayed per bin, so their numerical heights are not directly comparable across the two resolutions. The event-derived departure time is an activity-end decision; a simultaneous departure does not mean that all vehicles immediately enter the first full road link. Insertion and downstream discharge still constrain physical movement.')
    p('Morning travel-time distributions are retained in the accompanying ECDF figure and trip data. A lower mean is not sufficient to conclude that every agent benefits. The final comparison therefore also pairs individual people across scenarios and reports the spread of their time changes.')

    page('9  Daily plan scores and learning')
    fig('05_learning','Figure 3. Mean executed score by iteration. Lines average three runs; shading is the minimum-maximum range across seeds. The lower panel magnifies iterations 60-100. Scores use identical scoring settings across the five main scenarios.',445)
    p(f'The final mean executed score is {f("baseline","mean_score")} utils for Baseline, {f("capacity","mean_score")} for Capacity, {f("stagger","mean_score")} for Stagger, {f("combined","mean_score")} for Combined and {f("adaptive","mean_score")} for Adaptive. Executed score is used because it describes plans experienced that iteration. The best score held in plan memory can reflect an earlier traffic environment and is not a substitute for current performance.')
    p('The adaptive alternative changes both travel experience and activity timing. A larger score gain cannot be converted directly into monetary welfare or attributed wholly to congestion reduction. With 07:00 work opening, some early arrivals cannot obtain the same activity utility as later arrivals. Fixed-duration work and the unchanged scoring function keep the comparison interpretable, but they do not remove timing preferences from the result.')

    page('10  Route allocation and link states')
    fig('06_routes_links','Figure 4. Final route shares and mean full-link delays on links 11-19, seed 4711. Each outward trip traverses exactly one of these corridor links. Route shares total 100%; link delay excludes the free-speed traversal component.',470)
    p('Route shares reveal how agents distribute themselves across the nine corridors. Since all outward alternatives have the same declared lengths and free speeds, queues and score history can drive different shares without a geometric distance advantage. Low-congestion scenarios can preserve an uneven allocation when alternatives offer almost identical scores. Equal route use is therefore not a necessary condition for good network performance.')
    p(f'Mean corridor-link delay is {f("baseline","corridor_mean_delay_min")} minutes in Baseline, {f("capacity","corridor_mean_delay_min")} in Capacity, {f("stagger","corridor_mean_delay_min")} in Stagger and {f("combined","corridor_mean_delay_min")} in Combined, averaged across seeds. Delay is measured on the actual full-link traversal and compared with 5,000 / 27.78 seconds of nominal free-speed time. It includes queue waiting and QSim discretisation, so small positive residuals need not indicate a substantial queue.')
    p('Doubling capacity leaves one lane per treatment link. Thus, the intervention changes the rate at which queues can discharge, while the density denominator remains unchanged. A faster queue clearance can raise a short-bin exit flow even while mean travel time improves. That combination is not contradictory: throughput measures movement, while travel time measures the duration experienced by a vehicle.')

    page('11  Traffic dynamics through the peak')
    fig('07_link_dynamics','Figure 5. Five-minute link-state summaries for seed 4711. Top: summed exit flow and time-averaged occupancy on the nine corridor links. Bottom: full traversal time and density for link 12. Time bins are shared across scenarios.',475)
    p('Occupancy and exit flow answer different questions. Summed occupancy records how many vehicles are on the corridor links on average during a time interval. It includes both moving and queued vehicles, so it is not a direct queue-length observation. Exit flow records completed link traversals, expressed as an hourly rate. A high exit flow may describe successful clearance of a queue rather than a worsening condition.')
    p('The lower panels show a specific link rather than only the aggregate. Mean travel time groups completed traversals by entry time. Exit-flow bins group by exit time, so their peaks need not coincide. Density is calculated by exact integration of entry and exit events and division by 5 km and one lane. These definitions prevent a misleading direct comparison between a snapshot vehicle count, a bin-average density and a trip-weighted speed.')
    p('The pattern is consistent with the intended mechanisms: capacity changes the service rate; staggering changes the arrival pattern. Because both influence the same morning queues, their benefits can overlap. Link-level evidence should accompany the scenario mean when explaining why a combined intervention adds relatively little or substantially more than an individual measure.')

    page('12  Spatial and individual heterogeneity')
    fig('08_link_heatmap','Figure 6. Corridor delay by link and entry-time bin for Baseline and Combined, seed 4711. Both panels use the same 0-12 minute colour scale. White cells have no completed traversal entering that bin; they are not evidence of zero delay.',465)
    p('The heatmap preserves the identity of each treated link and the timing of its experienced delay. A network average can hide a badly performing route or conceal that a queue has merely shifted in time. Empty observations remain visibly separate from low-delay observations. The companion numerical link tables allow inspection without estimating values from colour.')
    p('The individual comparison pairs each person identifier between the baseline and an intervention at the same seed. Its outcome is baseline minus intervention morning duration; a positive value is a time saving. This pairing preserves the identity of an agent, but not necessarily their selected route or queue position. A small group can consequently experience a loss even when the total travel-time change is favourable.')
    p('Despite higher mean scores, 41.2-41.6% of agents have a lower executed-plan score under Stagger and Combined than under the paired baseline, across the three seeds. This measured tradeoff reflects scheduling as well as travel and cautions against equating average time savings with universal benefit.')
    p('No demographic variables are available. The analysis therefore describes heterogeneity in simulated experiences, not income, age or neighbourhood equity. The file-order assignment used for staggering is also not a realistic allocation rule for flexible work hours. A field study would need to measure schedule constraints and participation before treating this schedule as an implementable policy.')

    page('13  Robustness and remaining uncertainty')
    table(['Scenario','AM mean range (min)','Score tail change (utils)'],[[labels[s],f'{d[d.scenario==s].am_mean_min.min():.3f} - {d[d.scenario==s].am_mean_min.max():.3f}',f'{v(s,"score_tail_change"):+.4f}'] for s in order],[100,195,200])
    p('Table 5. The range spans three random seeds. Tail change is the mean executed score over iterations 91-100 minus its mean over iterations 81-90, averaged across seeds. It is a diagnostic of recent drift, not a statistical test of convergence. Replanning remains active, and small changes in selected plans can persist after the average has flattened.')
    if sensitivity:
        for item in sensitivity:
            p(f'An extended {item["scenario"]} run at seed {item["seed"]}, through iteration 200, gives morning travel time {item["am_mean_min"]:.3f} minutes versus {item["original_am_mean_min"]:.3f} at iteration 100. Its executed score changes from {item["original_score"]:.3f} to {item["mean_score"]:.3f} utils; the extended tail score change remains {item["score_tail_change"]:+.4f} utils. This is an independent rerun from the same initial inputs with a longer horizon, not an average over late-iteration event files.')
    p('The seeds are paired across scenarios, but their random streams can diverge when a scenario changes available actions. Pairing is useful for controlled bookkeeping and is not a guarantee of identical random draws at every behavioural decision. Three replications give only a limited view of algorithmic variability; the report shows ranges rather than presenting narrow confidence intervals as population evidence.')
    p('Five-minute and 15-minute link tables are both retained. Binning changes peak reported flow and density but cannot change the total completed-trip count or total travel time. Further sensitivity work should vary demand size, capacity increments, scheduling compliance, plan-memory settings and scoring parameters. These are proposed extensions, not experiments claimed to have been performed.')

    page('14  Interpretation for ITS planning')
    fig('09_individual_changes','Figure 7. Paired morning time savings for 2,000 agents, seed 4711. Violins show the distribution; points mark the 5th, 50th and 95th percentiles. Positive values indicate a shorter trip than the baseline.',465)
    interaction=v('combined','am_mean_min')-v('capacity','am_mean_min')-v('stagger','am_mean_min')+v('baseline','am_mean_min')
    p(f'The factorial interaction in morning travel time is {interaction:+.2f} minutes, computed as Combined - Capacity - Stagger + Baseline. A positive value means that the joint saving is smaller than the sum of the individual savings: the interventions partly remove the same delay. This arithmetic comparison describes the model response; it is not a regression-based causal estimate for an observed city.')
    p('An operational interpretation would compare measured bottleneck improvements with a scheduling programme. Capacity can be targeted to identified links, but construction cost, safety, emissions and implementation feasibility are not represented. Staggering avoids changing the network input, yet assumes full compliance and incurs unmodelled schedule inconvenience. Neither alternative can be labelled cost-effective from travel time alone.')
    p('The adaptive scenario illustrates how an ITS application that changes travellers\' timing choices can influence network use. Actual advice, incentives or employer coordination are not explicitly simulated. Before recommending such a programme, the next step would be to calibrate observed schedules and route choices, represent partial participation, and assess distributional impacts alongside time savings.')

    page('15  Conclusions and reproducibility')
    p(f'The project successfully constructs, executes and compares MATSim scenarios derived from the official equil example. In the five main scenarios, every replication completes all 4,000 trips without stuck agents. Compared with the congested reference, capacity expansion reduces mean morning duration by {improve("capacity"):.1f}%, staggering by {improve("stagger"):.1f}% and their combination by {improve("combined"):.1f}%. The adaptive-timing configuration changes morning duration by {improve("adaptive"):.1f}% in the beneficial direction under the selected scoring assumptions.')
    p('Three findings are central. First, traffic concentration is a distinct modelling dimension from the number of daily trips: identical trip totals can generate different travel experiences. Second, plan scores and travel times must be analysed together, because timing and activity utility affect the former. Third, link flow, occupancy and traversal delay provide the mechanism behind a network-level result; none of those indicators alone is sufficient to label a link congested.')
    p('The results remain conditional on a synthetic network and demand set. The study has no observed validation data, no mode choice, no demand growth, no land-use response and no cost model. The capacity treatment does not add lanes, and the scheduling treatment assumes an externally assigned departure pattern. Additional random seeds and longer runs can test numerical robustness, but cannot resolve those structural limitations.')
